mapper.select:
SELECT log_id, tenant_id, order_id, package_id, platform, platform_order_no,
       tracking_no, status, attempt_no, error_message, synced_at
FROM oms_platform_shipment_sync_log
WHERE tenant_id = #{tenantId}
  AND order_id = #{orderId}
ORDER BY synced_at DESC, attempt_no DESC, log_id DESC
